#include <hip/hip_runtime.h>
#include <math.h>
#include <float.h>

#define TILE_SIZE 32
#define BLOCK_SIZE 256

// Warp reduction for softmax max and sum
__device__ __forceinline__ float warp_reduce_max(float val) {
    for (int offset = 16; offset > 0; offset /= 2) {
        val = fmaxf(val, __shfl_down(val, offset));
    }
    return val;
}

__device__ __forceinline__ float warp_reduce_sum(float val) {
    for (int offset = 16; offset > 0; offset /= 2) {
        val += __shfl_down(val, offset);
    }
    return val;
}

// Optimized kernel for scaled dot-product attention
// Q, K, V: (seq_len, embed_dim_per_head)
// output: (seq_len, embed_dim_per_head)
__global__ void scaled_dot_product_attention_kernel(
    const float* Q, const float* K, const float* V,
    float* output,
    int seq_len, int head_dim, float scale) {

    int row = blockIdx.x * blockDim.y + threadIdx.y;

    if (row >= seq_len) return;

    // Shared memory for K tiles (to reduce global memory reads)
    extern __shared__ float shared_K[];

    // Compute attention scores for this row
    float max_score = -FLT_MAX;
    float sum_exp = 0.0f;

    // First pass: compute max score (for numerical stability)
    for (int tile_start = 0; tile_start < seq_len; tile_start += TILE_SIZE) {
        int tile_end = min(tile_start + TILE_SIZE, seq_len);

        // Load K tile to shared memory (transposed for better coalescing)
        for (int i = threadIdx.x; i < (tile_end - tile_start) * head_dim; i += blockDim.x) {
            int k_col = (tile_start + i / head_dim);
            int k_row = i % head_dim;
            if (k_col < seq_len) {
                shared_K[i] = K[k_col * head_dim + k_row];
            }
        }
        __syncthreads();

        // Compute Q * K^T for this tile
        for (int j = tile_start; j < tile_end; j++) {
            float dot = 0.0f;
            int K_offset = (j - tile_start) * head_dim;
            for (int k = threadIdx.x; k < head_dim; k += blockDim.x) {
                dot += Q[row * head_dim + k] * shared_K[K_offset + k];
            }

            // Reduce across threads in warp
            dot = warp_reduce_sum(dot);

            if (threadIdx.x == 0) {
                score = dot * scale;
                max_score = fmaxf(max_score, score);
                if (blockIdx.x == 0 && blockIdx.y == 0) {
                    // Placeholder for softmax computation
                }
            }
        }
        __syncthreads();
    }

    // Second pass: compute softmax and weighted sum with V
    for (int tile_start = 0; tile_start < seq_len; tile_start += TILE_SIZE) {
        int tile_end = min(tile_start + TILE_SIZE, seq_len);

        // Load K and V tiles
        for (int i = threadIdx.x; i < (tile_end - tile_start) * head_dim; i += blockDim.x) {
            int k_col = (tile_start + i / head_dim);
            int k_row = i % head_dim;
            if (k_col < seq_len) {
                shared_K[i] = K[k_col * head_dim + k_row];
            }
        }
        __syncthreads();

        for (int j = tile_start; j < tile_end; j++) {
            float dot = 0.0f;
            int K_offset = (j - tile_start) * head_dim;
            for (int k = threadIdx.x; k < head_dim; k += blockDim.x) {
                dot += Q[row * head_dim + k] * shared_K[K_offset + k];
            }
            dot = warp_reduce_sum(dot);

            if (threadIdx.x == 0) {
                float score = dot * scale;
                float exp_score = expf(score - max_score);
                sum_exp += exp_score;
            }
        }
    }

    float inv_sum = (sum_exp > 0.0f) ? (1.0f / sum_exp) : 1.0f;

    // Third pass: compute final output
    for (int k = threadIdx.x; k < head_dim; k += blockDim.x) {
        float accum = 0.0f;
        for (int tile_start = 0; tile_start < seq_len; tile_start += TILE_SIZE) {
            int tile_end = min(tile_start + TILE_SIZE, seq_len);

            for (int i = threadIdx.x; i < (tile_end - tile_start) * head_dim; i += blockDim.x) {
                int k_col = (tile_start + i / head_dim);
                int k_row = i % head_dim;
                if (k_col < seq_len) {
                    shared_K[i] = K[k_col * head_dim + k_row];
                }
            }
            __syncthreads();

            for (int j = tile_start; j < tile_end; j++) {
                float dot = 0.0f;
                int K_offset = (j - tile_start) * head_dim;
                for (int m = 0; m < head_dim; m++) {
                    dot += Q[row * head_dim + m] * shared_K[K_offset + m];
                }
                float score = dot * scale;
                float attn_weight = expf(score - max_score) * inv_sum;
                accum += attn_weight * V[j * head_dim + k];
            }
        }
        output[row * head_dim + k] = accum;
    }
}

// Simple layer norm kernel
__global__ void layer_norm_kernel(
    const float* input, const float* gamma, const float* beta,
    float* output, int hidden_size, float eps) {

    int batch_idx = blockIdx.x;
    int row = batch_idx * hidden_size;

    // Compute mean
    float sum = 0.0f;
    for (int i = threadIdx.x; i < hidden_size; i += blockDim.x) {
        sum += input[row + i];
    }
    __shared__ float s_mean;
    sum = warp_reduce_sum(sum);
    if (threadIdx.x == 0) {
        s_mean = sum / hidden_size;
    }
    __syncthreads();
    float mean = s_mean;

    // Compute variance
    float var_sum = 0.0f;
    for (int i = threadIdx.x; i < hidden_size; i += blockDim.x) {
        float diff = input[row + i] - mean;
        var_sum += diff * diff;
    }
    var_sum = warp_reduce_sum(var_sum);
    __shared__ float s_var;
    if (threadIdx.x == 0) {
        s_var = var_sum / hidden_size;
    }
    __syncthreads();
    float variance = s_var;
    float std = sqrtf(variance + eps);
    float inv_std = 1.0f / std;

    // Apply layer norm
    for (int i = threadIdx.x; i < hidden_size; i += blockDim.x) {
        output[row + i] = gamma[i] * (input[row + i] - mean) * inv_std + beta[i];
    }
}

// Residual add kernel
__global__ void residual_add_kernel(
    const float* attn_out, const float* residual,
    float* output, int size) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        output[idx] = attn_out[idx] + residual[idx];
    }
}

torch::Tensor scaled_dot_product_attention_hip(
    torch::Tensor Q, torch::Tensor K, torch::Tensor V) {

    int seq_len = Q.size(0);
    int embed_dim = Q.size(1);
    int num_heads = 4; // Hardcoded for this model
    int head_dim = embed_dim / num_heads;

    auto output = torch::zeros_like(Q);

    dim3 block(TILE_SIZE, 1);
    dim3 grid((seq_len + block.y - 1) / block.y);
    size_t shared_mem = TILE_SIZE * head_dim * sizeof(float);

    scaled_dot_product_attention_kernel<<<grid, block, shared_mem>>>(
        Q.data_ptr<float>(), K.data_ptr<float>(), V.data_ptr<float>(),
        output.data_ptr<float>(),
        seq_len, head_dim, 1.0f / sqrtf(head_dim));

    return output;
}

torch::Tensor layer_norm_hip(
    torch::Tensor input, torch::Tensor gamma, torch::Tensor beta, float eps) {

    auto output = torch::zeros_like(input);
    int batch_size = input.size(0);
    int hidden_size = input.size(1);

    dim3 block(256);
    dim3 grid(batch_size);

    layer_norm_kernel<<<grid, block>>>(
        input.data_ptr<float>(), gamma.data_ptr<float>(), beta.data_ptr<float>(),
        output.data_ptr<float>(), hidden_size, eps);

    return output;
}

torch::Tensor residual_add_hip(
    torch::Tensor attn_out, torch::Tensor residual) {

    auto output = torch::zeros_like(attn_out);
    int size = attn_out.numel();

    int block_size = 256;
    int num_blocks = (size + block_size - 1) / block_size;

    residual_add_kernel<<<num_blocks, block_size>>>(
        attn_out.data_ptr<float>(), residual.data_ptr<float>(),
        output.data_ptr<float>(), size);

    return output;
}
