masked_attention_cpp_source = """
#include <hip/hip_runtime.h>
#include <math.h>

__global__ void masked_attention_kernel(const float* q, const float* k, const float* v, float* out,
                                        const float* mask, int B, int nh, int, int hs, int T) {
    int b = blockIdx.x;
    int head = blockIdx.y;
    int t_out = blockIdx.z;  // output position

    if (b >= B || head >= nh || t_out >= T) return;

    int qkv_offset = (b * nh + head) * T * hs;
    const float* q_ptr = q + qkv_offset;
    const float* k_ptr = k + qkv_offset;
    const float* v_ptr = v + qkv_offset;

    // Compute attention scores for this output position
    // We only attend to positions [0, t_out]

    __shared__ float s_q[128];  // query for this position (shared across threads)
    __shared__ float s_v_sum[128];  // value accumulation
    __shared__ float s_mask[1024];  // mask for this row

    // Broadcast mask to shared memory
    int mask_row = t_out * T;
    for (int i = threadIdx.x; i < T; i += blockDim.x) {
        s_mask[i] = mask[mask_row + i];
    }
    __syncthreads();

    // Broadcast query to shared memory (all threads need it)
    for (int d = threadIdx.x; d < hs; d += blockDim.x) {
        s_q[d] = q_ptr[t_out * hs + d];
    }
    __syncthreads();

    // Clear output accumulation
    for (int d = threadIdx.x; d < hs; d += blockDim.x) {
        s_v_sum[d] = 0.0f;
    }
    __syncthreads();

    // Each thread computes dot products for a subset of positions
    // We have T positions in the sequence
    float scale = 1.0f / __sqrtf((float)hs);

    for (int t = threadIdx.x; t < T; t += blockDim.x) {
        int mask_val = (int)s_mask[t];  // 1 if valid, 0 otherwise

        if (mask_val > 0 && t <= t_out) {
            // Compute dot product: q[t_out] @ k[t]
            float dot = 0.0f;
            for (int d = 0; d < hs; d++) {
                dot += s_q[d] * k_ptr[t * hs + d];
            }

            float score = dot * scale;

            // For softmax, we need max and sum across valid positions
            // Store score in a reduction-friendly way
        }
    }

    // Compute max and exp sum via reduction
    extern __shared__ float shared[];

    float* s_scores = &shared[0];
    float* s_max = &shared[T];  // max reduction
    float* s_exp_sum = &shared[T + 32];  // exp sum reduction

    // Each thread computes its score(s)
    for (int t = threadIdx.x; t < T; t += blockDim.x) {
        if ((int)s_mask[t] > 0 && t <= t_out) {
            float dot = 0.0f;
            for (int d = 0; d < hs; d++) {
                dot += s_q[d] * k_ptr[t * hs + d];
            }
            s_scores[t] = dot * scale;
        } else {
            s_scores[t] = -1e20f;  // effectively -inf
        }
    }
    __syncthreads();

    // Find max
    float local_max = -1e20f;
    for (int t = threadIdx.x; t < T; t += blockDim.x) {
        if (s_scores[t] > local_max) local_max = s_scores[t];
    }

    // Reduction within warp
    #pragma unroll
    for (int offset = 16; offset > 0; offset /= 2) {
        local_max = __fmaxf(local_max, __shfl_down(local_max, offset));
    }

    // Get lane max
    if ((threadIdx.x % warpSize) == 0) {
        atomicMax(&s_max[threadIdx.x / warpSize], local_max);
    }
    __syncthreads();

    float global_max = s_max[0];
    for (int i = 1; i < (blockDim.x + warpSize - 1) / warpSize; i++) {
        if (s_max[i] > global_max) global_max = s_max[i];
    }

    // Broadcast global max
    if (threadIdx.x == 0) s_max[0] = global_max;
    __syncthreads();
    global_max = s_max[0];

    // Compute exp and sum
    float exp_sum_local = 0.0f;
    for (int t = threadIdx.x; t < T; t += blockDim.x) {
        if ((int)s_mask[t] > 0 && t <= t_out) {
            s_scores[t] = expf(s_scores[t] - global_max);
            exp_sum_local += s_scores[t];
        } else {
            s_scores[t] = 0.0f;
        }
    }

    // Reduction within warp
    #pragma unroll
    for (int offset = 16; offset > 0; offset /= 2) {
        exp_sum_local += __shfl_down(exp_sum_local, offset);
    }

    if ((threadIdx.x % warpSize) == 0) {
        atomicAdd(&s_exp_sum[threadIdx.x / warpSize], exp_sum_local);
    }
    __syncthreads();

    float global_exp_sum = 0.0f;
    for (int i = 0; i < (blockDim.x + warpSize - 1) / warpSize; i++) {
        global_exp_sum += s_exp_sum[i];
    }

    // Apply attention weights to values
    for (int t = threadIdx.x; t < T; t += blockDim.x) {
        if ((int)s_mask[t] > 0 && t <= t_out) {
            float weight = s_scores[t] / global_exp_sum;

            // Multiply and add to output for this position
            for (int d = 0; d < hs; d++) {
                atomicAdd(&s_v_sum[d], weight * v_ptr[t * hs + d]);
            }
        }
    }
    __syncthreads();

    // Write output
    int out_offset = qkv_offset + t_out * hs;
    for (int d = threadIdx.x; d < hs; d += blockDim.x) {
        out[out_offset + d] = s_v_sum[d];
    }
}

torch::Tensor masked_attention_hip(torch::Tensor q, torch::Tensor k, torch::Tensor v, torch::Tensor mask, float scale) {
    int B = q.size(0);
    int nh = q.size(1);
    int T = q.size(2);
    int hs = q.size(3);

    auto out = torch::zeros_like(q);

    int threads = 256;
    int shared_size = (3 * T + 128) * sizeof(float) + 64 * sizeof(float);  // Extra for reductions

    dim3 grid(B, nh, T);

    masked_attention_kernel<<<grid, threads, shared_size>>>(
        q.data_ptr<float>(),
        k.data_ptr<float>(),
        v.data_ptr<float>(),
        out.data_ptr<float>(),
        mask.data_ptr<float>(),
        B, nh, 0, hs, T
    );

    return out;
}
