# HIP kernel for fused residual + layer norm
# This is a simpler kernel that's more likely to compile and work correctly
residual_layernorm_source = """
#include <hip/hip_runtime.h>
#include <math.h>

__device__ __forceinline__ float warp_reduce_sum(float val) {
    for (int offset = 16; offset > 0; offset /= 2) {
        val += __shfl_down(val, offset);
    }
    return val;
}

__global__ void fused_residual_layernorm_kernel(
    const float* attn_out, const float* residual,
    const float* gamma, const float* beta,
    float* output,
    int batch_size, int hidden_size, float eps) {

    int batch_idx = blockIdx.x;
    int seq_idx = blockIdx.y;
    int row = (batch_idx * gridDim.y + seq_idx) * hidden_size;

    // Compute mean of (attn_out + residual)
    float sum = 0.0f;
    for (int i = threadIdx.x; i < hidden_size; i += blockDim.x) {
        float val = attn_out[row + i] + residual[row + i];
        sum += val;
    }
    __shared__ float s_mean;
    sum = warp_reduce_sum(sum);
    if (threadIdx.x == 0) {
        s_mean = sum / hidden_size;
    }
    __syncthreads();
    float mean = s_mean;

    // Compute variance
    float var_sum = 0.0f;
    for (int i = threadIdx.x; i < hidden_size; i += blockDim.x) {
        float val = attn_out[row + i] + residual[row + i];
        float diff = val - mean;
        var_sum += diff * diff;
    }
    var_sum = warp_reduce_sum(var_sum);
    __shared__ float s_var;
    if (threadIdx.x == 0) {
        s_var = var_sum / hidden_size;
    }
    __syncthreads();
    float variance = s_var;
    float std = sqrtf(variance + eps);
    float inv_std = 1.0f / std;

    // Apply layer norm: output = gamma * ((x - mean) / std) + beta
    for (int i = threadIdx.x; i < hidden_size; i += blockDim.x) {
        float residual_val = residual[row + i];
        float attn_val = attn_out[row + i];
        float combined = attn_val + residual_val;
        output[row + i] = gamma[i] * (combined - mean) * inv_std + beta[i];
    }
}

torch::Tensor fused_residual_layernorm_hip(
    torch::Tensor attn_out, torch::Tensor residual,
    torch::Tensor gamma, torch::Tensor beta, float eps) {

