import math
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

masked_attention_cpp_source = """
#include <hip/hip_runtime.h>
#include <math.h>

__device__ inline float warp_reduce_max(float val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val = fmaxf(val, __shfl_down(val, offset));
    return val;
}

__device__ inline float warp_reduce_sum(float val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val += __shfl_down(val, offset);
    return val;
}

__global__ void masked_attention_kernel(const float* q, const float* k, const float* v, float* out,
                                        const float* mask, int B, int nh, int, int hs, int T) {
    int b = blockIdx.x;
    int head = blockIdx.y;
    int t_out = blockIdx.z;  // output position

    if (b >= B || head >= nh || t_out >= T) return;

    int qkv_offset = (b * nh + head) * T * hs;
    const float* q_ptr = q + qkv_offset;
    const float* k_ptr = k + qkv_offset;
    const float* v_ptr = v + qkv_offset;

    __shared__ float s_q[128];  // query for this position
    __shared__ float s_v_sum[128];  // value accumulation
    __shared__ float s_mask[1024];  // mask for this row

    // Broadcast mask to shared memory
    int mask_row = t_out * T;
    for (int i = threadIdx.x; i < T; i += blockDim.x) {
        s_mask[i] = mask[mask_row + i];
    }
    __syncthreads();

    // Broadcast query to shared memory
    for (int d = threadIdx.x; d < hs; d += blockDim.x) {
        s_q[d] = q_ptr[t_out * hs + d];
    }
    __syncthreads();

    // Clear output accumulation
    for (int d = threadIdx.x; d < hs; d += blockDim.x) {
        s_v_sum[d] = 0.0f;
    }
    __syncthreads();

    // Compute scale
    float scale = 1.0f / sqrtf((float)hs);

    // Shared memory for scores and reductions
    extern __shared__ float shared[];
    float* s_scores = &shared[0];
    float* s_max = &shared[T];
    float* s_exp_sum = &shared[T + 32];

    // Initialize reduction storage
    if (threadIdx.x == 0) {
        for (int i = 0; i < (blockDim.x + 31) / 32; i++) {
            s_max[i] = -1e20f;
            s_exp_sum[i] = 0.0f;
        }
    }
    __syncthreads();

    // Each thread computes scores for its assigned positions
    float local_max = -1e20f;
    for (int t = threadIdx.x; t < T; t += blockDim.x) {
        if ((int)s_mask[t] > 0 && t <= t_out) {
            float dot = 0.0f;
            for (int d = 0; d < hs; d++) {
                dot += s_q[d] * k_ptr[t * hs + d];
            }
            s_scores[t] = dot * scale;
            if (s_scores[t] > local_max) local_max = s_scores[t];
        } else {
            s_scores[t] = -1e20f;
        }
    }

    // Reduction for max
    local_max = warp_reduce_max(local_max);
    int warp_id = threadIdx.x / 32;
    int lane_id = threadIdx.x % 32;

    if (lane_id == 0) {
        atomicMax((unsigned int*)&s_max[warp_id], __float_as_uint(local_max));
    }
    __syncthreads();

    float global_max = s_max[0];
    for (int i = 1; i < (blockDim.x + 31) / 32; i++) {
        if (s_max[i] > global_max) global_max = s_max[i];
    }

    // Compute exp and sum
    float exp_sum_local = 0.0f;
    for (int t = threadIdx.x; t < T; t += blockDim.x) {
        if ((int)s_mask[t] > 0 && t <= t_out) {
            s_scores[t] = expf(s_scores[t] - global_max);
            exp_sum_local += s_scores[t];
        } else {
            s_scores[t] = 0.0f;
        }
    }

    exp_sum_local = warp_reduce_sum(exp_sum_local);

    if (lane_id == 0) {
        atomicAdd(&s_exp_sum[warp_id], exp_sum_local);
    }
    __syncthreads();

    float global_exp_sum = 0.0f;
    for (int i = 0; i < (blockDim.x + 31) / 32; i++) {
        global_exp_sum += s_exp_sum[i];
    }

    // Apply attention weights to values
    for (int t = threadIdx.x; t < T; t += blockDim.x) {
        if ((int)s_mask[t] > 0 && t <= t_out) {
            float weight = s_scores[t] / global_exp_sum;

            for (int d = 0; d < hs; d++) {
                atomicAdd(&s_v_sum[d], weight * v_ptr[t * hs + d]);
            }
        }
    }
    __syncthreads();

    // Write output
    int out_offset = qkv_offset + t_out * hs;
    for (int d = threadIdx.x; d < hs; d += blockDim.x) {
        out[out_offset + d] = s_v_sum[d];
    }
}

torch::Tensor masked_attention_hip(torch::Tensor q, torch::Tensor k, torch::Tensor v, torch::Tensor mask, float scale) {
    int B = q.size(0);
    int nh = q.size(1);
    int T = q.size(2);
    int hs = q.size(3);

    auto out = torch::zeros_like(q);

    int threads = 256;
    int shared_size = (T + 128) * sizeof(float) * 2;  // s_scores + s_max + s_mask etc.

    dim3 grid(B, nh, T);

    masked_attention_kernel<<<grid, threads, shared_size>>>(
        q.data_ptr<float>(),
        k.data_ptr<float>(),
        v.data_ptr<float>(),
        out.data_ptr<float>(),
        mask.data_ptr<float>(),
        B, nh, 0, hs, T
    );

    return out;
}
"""

masked_attention = load_inline(
    name="masked_attention",
    cpp_sources=masked_attention_cpp_source,
    functions=["masked_attention_hip"],
    verbose=True,
)


class ModelNew(nn.Module):
    """
    Optimized multi-head masked self-attention layer with fused attention kernel.
    """

    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        assert n_embd % n_head == 0
        # key, query, value projections for all heads, but in a batch
        self.c_attn = nn.Linear(n_embd, 3 * n_embd)
        # output projection
        self.c_proj = nn.Linear(n_embd, n_embd)
        # regularization
        self.attn_dropout = nn.Dropout(attn_pdrop)
        self.resid_dropout = nn.Dropout(resid_pdrop)
        # causal mask to ensure that attention is only applied to the left in the input sequence
        self.register_buffer("bias", torch.tril(torch.ones(max_seqlen, max_seqlen))
                                     .view(1, 1, max_seqlen, max_seqlen))
        self.n_head = n_head
        self.n_embd = n_embd
        self.masked_attention = masked_attention

    def forward(self, x):
        B, T, C = x.size() # batch size, sequence length, embedding dimensionality (n_embd)

        # calculate query, key, values for all heads in batch and move head forward to be the batch dim
        q, k, v = self.c_attn(x).split(self.n_embd, dim=2)
        k = k.view(B, T, self.n_head, C // self.n_head).transpose(1, 2) # (B, nh, T, hs)
        q = q.view(B, T, self.n_head, C // self.n_head).transpose(1, 2) # (B, nh, T, hs)
        v = v.view(B, T, self.n_head, C // self.n_head).transpose(1, 2) # (B, nh, T, hs)

        # Compute masked attention with fused kernel (includes QK, softmax scaling, softmax, and @V)
        scale = 1.0 / math.sqrt(k.size(-1))
        y = self.masked_attention.masked_attention_hip(q, k, v, self.bias[0, 0, :T, :T], scale)

        # re-assemble all head outputs side by side
        y = y.transpose(1, 2).contiguous().view(B, T, C)

        # output projection
        y = self.resid_dropout(self.c_proj(y))
        return y


