gelu_source = """
#include <hip/hip_fp16.h>
#include <hip/hip_runtime.h>

__global__ void gelu_kernel(const float* __restrict__ input, float* __restrict__ output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x = input[idx];
        float x3 = x * x * x;
        float tanh_arg = sqrtf(2.0f / 3.14159265358979323846f) * (x + 0.044715f * x3);
        float tanh_val = tanhf(tanh_arg);
        output[idx] = 0.5f * x * (1.0f + tanh_val);
    }
}

torch::Tensor gelu_hip(torch::Tensor input) {
    auto size = input.numel();
    auto output = torch::empty_like(input);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    gelu_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), size);
    return output;
}
