__global__ void fused_residual_layernorm_kernel(
    const float* attn_out, const float* residual,
    const float* gamma, const float* beta,
    float* output,
    int total_rows, int hidden_size, float eps) {

    int row = blockIdx.x * blockDim.y + threadIdx.y;
    int tid = threadIdx.x;

    if (row >= total_rows) return;

    // Shared memory for reduction
    __shared__ float sdata[32];

    // Compute mean of (attn_out + residual)
    // Each thread handles multiple elements
    float sum = 0.0f;
    for (int i = tid; i < hidden_size; i += blockDim.x) {
        int idx = row * hidden_size + i;
        float val = attn_out[idx] + residual[idx];
        sum += val;
    }

    // Reduce within warp
    sum = warp_reduce_sum(sum);

    // Write to shared memory (only first thread in each warp)
    int lane_id = tid % 32;
    int warp_id = tid / 32;
    if (lane_id == 0) {
        sdata[warp_id] = sum;
    }
    __syncthreads();

    // Final reduction
    sum = 0.0f;
    if (tid < (blockDim.x + 31) / 32) {
        sum = sdata[tid];
    }
    sum = warp_reduce_sum(sum);

    // Broadcast mean
    __shared__ float mean_shared;
    if (tid == 0) {
        mean_shared = sum / hidden_size;
    }
    __syncthreads();
    float mean = mean_shared;

    // Compute variance
    float var_sum = 0.0f;
    for (int i = tid; i < hidden_size; i += blockDim.x) {
        int idx = row * hidden_size + i;
        float combined = attn_out[idx] + residual[idx];
        float diff = combined - mean;
        var_sum += diff * diff;
    }

    var_sum = warp_reduce_sum(var_sum);
    if (lane_id == 0) {
        sdata[warp_id] = var_sum;
    }
    __syncthreads();

    var_sum = 0.0f;
    if (tid < (blockDim.x + 31) / 32) {
        var_sum = sdata[tid];
    }
    var_sum = warp_reduce_sum(var_sum);

    __shared__ float var_shared;
    if (tid == 0) {
        var_shared = var_sum / hidden_size;
    }
    __syncthreads();
    float variance = var_shared;
    float inv_std = 1.0f / sqrtf(variance + eps);

    // Apply layer norm: output = gamma * ((x - mean) / std) + beta
    for (int i = tid; i < hidden_size; i += blockDim.x) {
        int idx = row * hidden_size + i;
        float combined = attn_out[idx] + residual[idx];
        output[idx] = gamma[i] * (combined - mean) * inv_std + beta[i];
    }
