gelu_code = """
#include <hip/hip_runtime.h>

__global__ void gelu_fwd(const float* x, float* y, int n) {
  int i = blockIdx.x * blockDim.x + threadIdx.x;
  if (i < n) {
    float xi = x[i];
    float tanh_in = 0.7978845608028654f * (xi + 0.044715f * xi * xi * xi);
    float tanh_out = tanhf(tanh_in);
    y[i] = 0.5f * xi * (1.0f + tanh_out);
  }
}

torch::Tensor gelu(torch::Tensor x) {
  auto y = torch::empty_like(x);
  int n = x.numel();
  int bs = 256;
  int gs = (n + bs - 1) / bs;
  gelu_fwd<<<gs, bs>>>(x.data_ptr<float>(), y.data_ptr<float>(), n);
  return y;
}
